//! Day, evening and night shares (END: 07-19, 19-23, 23-07) of a road's daily traffic by country,
//! road group (motorways and trunks with their links, primary roads, every other road) and vehicle
//! weight (light; medium and heavy). Generated by period-shares.py (private evidence
//! 2026-10-02/period-shares). Measured: hourly counts in the US (FHWA TMAS 2025, 8,056 stations),
//! Japan (road traffic census 2021, weekdays, 16,517 sections, small and large vehicles apart),
//! Germany (Baden-Wuerttemberg's permanent counters 2025, lorries apart), the Netherlands (INWEVA
//! 2024, national roads, lorries apart) and Great Britain (DfT 2025, all roads, HGVs apart), and
//! the sound energy at roadside noise monitors in Spain (Madrid and Barcelona 2025) and Thailand
//! (PCD 2025-26). Lorries run less in the evening and more at night than cars wherever they are
//! counted apart. A country without its own measurement of a group takes the median of the
//! measured countries in its UN M49 region (Europe outside the south as one region); the rest of
//! the world keeps the default, which lies between the measured patterns.

use physics::bands::PERIODS;

/// Road groups: motorways and trunks with their links; primary roads and links; other roads.
pub(crate) const GROUPS: usize = 3;

/// Shares where nothing is measured, light and heavy alike: between the counted temperate pattern
/// (US, Japan, Germany, the Netherlands, Britain: 0.75-0.81 by day, 0.09-0.15 in the evening,
/// 0.07-0.13 at night) and the late ones (Spain 0.68/0.19/0.13, Thailand 0.63/0.18/0.19).
pub(crate) const DEFAULT_PERIOD_SHARES: [[f64; PERIODS]; GROUPS] = [
    [0.65, 0.20, 0.15],
    [0.70, 0.18, 0.12],
    [0.70, 0.18, 0.12],
];

/// Each group's shares of its light vehicles and of its medium and heavy ones.
type GroupShares = [[[f64; PERIODS]; 2]; GROUPS];

